			while (l >= 0 && r < n)
				if (s[l] == '1' && s[r] == '2') --l, ++r, len += 2;  // 左右同时寻找，所以是 +2
				else break;  // 不满足了及时break
			ans = max(ans, len);
		}
	}
	write<int>(ans);
	return 0;
}

```

