#include <bits/stdc++.h>

using namespace std;

int num;

void run(int a, int b, int c, int d) {  //  a <= x <= b b <= y <= c c <= z <= d
    if (b + c - 1 <= d)
        printf ("%d %d %d\n", b, c, b + c - 1);
    else
        printf ("%d %d %d\n", b, c, d);
}

int main() {
    scanf("%d", &num);
    for (int i = 0; i < num; i++) {
        int a, b, c, d;
        scanf("%d%d%d%d", &a, &b, &c, &d);
        run(a, b, c, d);
