      for (int i = 0;i < n;++i) if (s[i] == 'A') {  // 注意到和 B 无关因此要判断
        if (i % 2) ++b;  // %2 余 0 就是 false，余 1 就是 true，正好分别对应偶数和奇数
        else ++a;
    }
    if ((abs(b - a)) % 2) cout << -1 << endl;  // 不知道谁大谁小，因此要取绝对值
    else cout << ((abs(b - a)) >> 1) << endl;  // 右移 1 位相当于除以 2，因为是非负数所以和 / 2 没有区别
    return 0;
}
