                if (s[j] == '?') a[i][j + 1] = -INF;
                else a[i][j + 1] = s[j] - '0';
            }
        }
        FOR(i, 1, n) FOR(j, 1, m) FOR(k, 0, x) {
              // 要用到 k - 1, 必须正序遍历。
            switch(a[i][j]) {
                case -INF:
                    if (k > 0) dp[i][j][k] = max(dp[i][j - 1][k - 1], dp[i - 1][j][k - 1]) + 1;
